      "stem": "甲公司於 X1 年初以平價發行面額$5,000,000，五年期之可轉換公司債，持有人可於到期日前以每股$50 之轉換價格，將該公司債轉換為甲公司之普通股(每股面額$10)，甲公司於發行日認列該可轉換公司債相關之「資本公積—認股權」金額$300,000。發行日甲公司普通股市價為每股$40。X3 年初該公司債之帳面金額為$4,900,000，甲公司為誘導該公司債持有人提前行使轉換權，宣布將轉換價格調降至每股$40，當日普通股市價為每股$60，該公司債之持有人於當日全部轉換為普通股，則甲公司認列該公司債轉換之相關分錄應包括：",
