      "stem": "開陽公司某一現金產生單位甲部門因所處產業環境發生不利變動，於本期發生減損損失 $80,000，該部門內有機器設備 A、B、C 及商譽，帳面金額分別為$90,000、$50,000、 $160,000 及$30,000，則機器 A 應分攤之減損損失為：",
