      "subject": "accounting",
      "sourceId": "accounting-06",
      "number": 13,
      "stem": "某公司 X7 年 1 月 1 日以$2,391,763 售出票面金額$2,500,000，五年期，利率 4%公司債，發行時市場利率 5%，利息於每年 1 月 1 日支付一次。公司債折（溢）價採有效利率法攤銷，設該債券於 X8 年 1 月 1 日於支付利息後，按面額 98 償還流通在外債券一半，試問 X8 年 1 月 1 日贖回債券損益為：",
