      "stem": "大仁公司有一機器設備，成本為$5,000,000，一開始估計可用十年，殘值估計為零，依直線法提列折舊。到第六年初該公司發現該設備預計還可再使用八年，殘值為$100,000，則第六年的折舊費用應為多少？",
