      "session": 2,
      "subject": "accounting",
      "sourceId": "accounting-02",
      "number": 16,
      "stem": "菁英金屬公司於 2016 年底的存貨盤點時，忘記盤點某些商品。請說明此項過失對該公司的 2016 年度銷貨毛利及 2017 年度的淨利之影響效果為何？（高估；低估；無影響）",
