      "session": 2,
      "subject": "accounting",
      "sourceId": "accounting-09",
      "number": 17,
      "stem": "遨遊科技控股公司 2023 年期初「預付租金」會計科目餘額為$80,000，期末餘額為$60,000，已知該公司於 2023 年度以現金$120,000 支付租金。試問：該公司 2023 年綜合損益表的租金費用應為多少？",
