      "subject": "accounting",
      "sourceId": "accounting-23",
      "number": 19,
      "stem": "已知立人國際公司 2023 年度的稅後純益為$100,000，累積特別股為$200,000，特別股股利率為 6%，當年度未宣告發放。此外，該公司於 2023 年度的普通股資料如下： 1/1 流通在外股數 10,000 股。 3/1 買入庫藏股票 960 股。 5/1 發放 20%股票股利。 7/1 現金增資 2,500 股。 9/1 出售庫藏股票 600 股。 11/1 股票分割 1 股分為 2 股。試問：立人國際公司 2023 年度的每股盈餘(EPS)為多少？",
