      "number": 21,
      "stem": "已知中信公司 2023 年度稅前淨利為$560,000，利息費用$50,000，所得稅率 25%；該公司部分財務資料如下： 1/1 12/31 總資產 $1,040,000 1,360,000 股東權益 1,000,000 1,160,000 特別股股本 8%；面值 ($10) 400,000 400,000 試問：中信公司 2023 年的財務槓桿指數(Financial Leverage Index)為多少？",
