      "subject": "accounting",
      "sourceId": "accounting-01",
      "number": 27,
      "stem": "明基食品公司在成立後的第一年度營運中，產生$73,200,000 的銷貨淨額，當年度採用直接沖銷法沖銷的壞帳金額計$1,267,200，第一年度的稅後淨利為$2,707,200。此外，該公司在第二年的營運中，銷貨淨利為$91,200,000，採用直接沖銷法沖銷的壞帳計$1,548,000，第二年度的稅後淨利為$389,200。試問：若明基食品公司在第一年與第二年度皆改採用「備抵法」提列壞帳（估計壞帳為銷貨淨額的 2%），則該公司第二年底備抵壞帳之餘額有多少？",
