      "stem": "某公司於 2021 年 7 月 24 日將閒置資金購入濟業公司股票 5,000 股，每股面額$10，市價每股為$28，另付 1.5 ‰費用，其分錄為借：透過其他綜合損益按公允價值衡量之金融資產－股票，依 IFRS9 規定，入帳金額應為多少？",
