      "stem": "力麒公司於 2022 年初以面額發行 2,000 張、每張 1,000 元的三年期可轉換公司債，票面利率為 6%，每年付息一次，每張公司債可轉換 30 股、每股面額 10 元的普通股。若該公司債發行時，條件相同但不可轉換的公司債之發行價格為$1,900,000，試問：力麒公司於 2022 年初發行時應付公司債的帳面價值為多少？",
