      "stem": "大華工具機公司於 2022 年取得專門生產新機器手臂的專利，下列資訊取自該公司的內部財務紀錄：2022 年期間，大華公司申請專利時支付了＄1,200,000 的法律與申請費用。此外，大華公司於 2022 年期間，因控告其他公司違反專利權法，故產生了＄4,800,000 的法律訴訟費，這筆費用將於 2023 年支付。此項專利於 2022 年 12 月 31 日生效，大華公司估計這項專利將為公司未來五年期間帶來經濟利益，該公司的政策是在取得專利的當年度不予攤銷無形資產。對於其他公司侵犯專利權的行為，若大華公司已成功地捍衛其專利權。試問：大華工具機公司於 2023 年 12 月 31 日的財務狀況表中，專利權的帳面價值為多少？",
